// Looks at every row once and returns ONE item: the CREATE TABLE statement.
// The rows themselves are inserted by the Postgres Insert node, outside the task runner.
const form = $('Upload Dataset').first();
const fileName = (form.binary && form.binary.dataset && form.binary.dataset.fileName) || 'dataset.csv';
const clean = (s) => {
  let n = String(s || '').trim().toLowerCase().replace(/[^a-z0-9_]+/g, '_').replace(/^_+|_+$/g, '');
  if (!n) n = 'col';
  if (/^[0-9]/.test(n)) n = 't_' + n;
  return n.slice(0, 60);
};
const tableName = clean(form.json.table_name || fileName.replace(/\.[^.]+$/, ''));

const items = $input.all();
if (items.length === 0) throw new Error('The uploaded file has no rows.');
const cols = Object.keys(items[0].json);

// Guess a type per column: BIGINT, NUMERIC, DATE, or TEXT
// Codes with leading zeros (phone numbers, IDs like 00123) stay TEXT so the zeros aren't lost
const isInt = v => /^-?\d+$/.test(v) && v.replace('-', '').length < 18;
const isNum = v => /^-?\d*\.?\d+(e[-+]?\d+)?$/i.test(v);
const isDate = v => /^\d{4}-\d{2}-\d{2}$/.test(v);
const st = cols.map(() => ({ any: false, lead: false, int: true, num: true, date: true }));
for (const it of items) {
  const r = it.json;
  for (let i = 0; i < cols.length; i++) {
    const t = st[i];
    if (t.lead) continue;
    const v = r[cols[i]];
    if (v === null || v === undefined) continue;
    const s = String(v).trim();
    if (!s) continue;
    t.any = true;
    if (/^-?0\d/.test(s)) { t.lead = true; continue; }
    if (t.int && !isInt(s)) t.int = false;
    if (t.num && !isNum(s)) t.num = false;
    if (t.date && !isDate(s)) t.date = false;
  }
}
const types = st.map(t => (!t.any || t.lead) ? 'TEXT' : t.int ? 'BIGINT' : t.num ? 'NUMERIC' : t.date ? 'DATE' : 'TEXT');

const createSql = 'CREATE TABLE IF NOT EXISTS public."' + tableName + '" (' +
  cols.map((c, i) => '"' + c + '" ' + types[i]).join(', ') +
  ', loaded_at TIMESTAMP DEFAULT now());';

let rowsUploaded = items.length;
try { rowsUploaded = $('Read CSV').all().length; } catch (e) {}
return [{ json: { table: tableName, createSql, rowsUploaded, rowsAfterCleaning: items.length } }];

const items = $input.all();
const rowsIn = items.length;
const NULLS = new Set(['', 'na', 'n/a', '#n/a', 'null', 'none', 'nil', 'nan', '-', '--', '?', '#value!', '#div/0!', '#ref!']);
const MONTHS = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, oct: 10, nov: 11, dec: 12 };
const fromExcel = (() => { try { return $('Read Excel').isExecuted; } catch (e) { return false; } })();

// 1. Trim text, remove hidden characters, turn NA / null / - etc. into real NULLs
const cleanText = (v) => {
  if (v === null || v === undefined) return null;
  const s = String(v).replace(/\u00a0/g, ' ').replace(/[\u200b-\u200d\ufeff]/g, '').replace(/\s+/g, ' ').trim();
  return NULLS.has(s.toLowerCase()) ? null : s;
};

// 2. Numbers: strip thousands separators and currency (Tk, BDT, $), (123) -> -123
const cleanNumber = (s) => {
  let t = s.replace(/^(৳|tk\.?|bdt|\$|€|£)\s*/i, '').replace(/\s*(৳|tk\.?|bdt)$/i, '');
  let neg = false;
  if (/^\(.*\)$/.test(t)) { neg = true; t = t.slice(1, -1).trim(); }
  if (/^-?\d{1,3}(,\d{3})+(\.\d+)?$/.test(t)) t = t.replace(/,/g, '');
  if (/^-?\d+(\.\d+)?$/.test(t)) return (neg && !t.startsWith('-') ? '-' : '') + t;
  return s;
};

// 3. Header names: SQL-safe snake_case, blank headers named, duplicates made unique
const sqlName = (s) => {
  let n = String(s || '').trim().toLowerCase().replace(/[^a-z0-9_]+/g, '_').replace(/^_+|_+$/g, '');
  if (!n) n = 'col';
  if (/^[0-9]/.test(n)) n = 't_' + n;
  if (n === 'loaded_at') n = 'loaded_at_src';
  return n.slice(0, 55);
};
const rawKeys = [];
for (const it of items) for (const k of Object.keys(it.json)) if (!rawKeys.includes(k)) rawKeys.push(k);
const headerMap = {};
const used = new Set();
rawKeys.forEach((k, i) => {
  let h = cleanText(k);
  if (!h || /^__EMPTY/.test(h)) h = 'column_' + (i + 1);
  h = sqlName(h);
  let name = h, n = 2;
  while (used.has(name)) name = h + '_' + n++;
  used.add(name);
  headerMap[k] = name;
});
const cols = rawKeys.map(k => headerMap[k]);

let rows = items.map(it => {
  const r = {};
  for (const k of rawKeys) {
    const v = cleanText(it.json[k]);
    r[headerMap[k]] = v === null ? null : cleanNumber(v);
  }
  return r;
});

// 4. Drop fully empty rows and exact duplicate rows
rows = rows.filter(r => cols.some(c => r[c] !== null));
const seenRows = new Set();
rows = rows.filter(r => {
  const key = JSON.stringify(cols.map(c => r[c]));
  if (seenRows.has(key)) return false;
  seenRows.add(key);
  return true;
});

// 5. Drop columns that are empty in every row
const keepCols = cols.filter(c => rows.some(r => r[c] !== null));

// 6. Dates: convert a column to YYYY-MM-DD only if every value in it is a valid date
const yr = (y) => { y = Number(y); return y < 100 ? 2000 + y : y; };
const mon = (s) => MONTHS[String(s).slice(0, 3).toLowerCase()];
const parseDate = (s) => {
  let m = s.match(/^(\d{4})[-\/.](\d{1,2})[-\/.](\d{1,2})$/);
  if (m) return { k: 'ymd', y: +m[1], a: +m[2], b: +m[3] };
  m = s.match(/^(\d{1,2})[-\/.](\d{1,2})[-\/.](\d{4}|\d{2})$/);
  if (m) return { k: 'xx', y: yr(m[3]), a: +m[1], b: +m[2] };
  m = s.match(/^(\d{1,2})[-\s]([a-z]{3,9})\.?[-\s,]+(\d{4}|\d{2})$/i);
  if (m && mon(m[2])) return { k: 'md', y: yr(m[3]), a: mon(m[2]), b: +m[1] };
  m = s.match(/^([a-z]{3,9})\.?\s+(\d{1,2}),?\s+(\d{4})$/i);
  if (m && mon(m[1])) return { k: 'md', y: +m[3], a: mon(m[1]), b: +m[2] };
  return null;
};
const isValid = (y, mo, d) => {
  const dt = new Date(Date.UTC(y, mo - 1, d));
  return mo >= 1 && mo <= 12 && dt.getUTCFullYear() === y && dt.getUTCMonth() === mo - 1 && dt.getUTCDate() === d;
};
const pad = (n) => String(n).padStart(2, '0');
for (const c of keepCols) {
  const vals = [...new Set(rows.map(r => r[c]).filter(v => v !== null))];
  const parsed = vals.map(parseDate);
  if (parsed.length === 0 || parsed.some(p => p === null)) continue;
  const xx = parsed.filter(p => p.k === 'xx');
  const aBig = xx.some(p => p.a > 12), bBig = xx.some(p => p.b > 12);
  if (aBig && bBig) continue;
  // dd/mm/yyyy by default; Excel's own display format is m/d/yy, so Excel uploads default to month first
  const dayFirst = aBig ? true : bBig ? false : !fromExcel;
  const isos = parsed.map(p => {
    let mo = p.a, d = p.b;
    if (p.k === 'xx' && dayFirst) { mo = p.b; d = p.a; }
    return isValid(p.y, mo, d) ? p.y + '-' + pad(mo) + '-' + pad(d) : null;
  });
  if (isos.some(v => v === null)) continue;
  const map = new Map(vals.map((v, i) => [v, isos[i]]));
  rows.forEach(r => { if (r[c] !== null) r[c] = map.get(r[c]); });
}

if (rows.length === 0) throw new Error('No usable rows left after cleaning (' + rowsIn + ' rows uploaded).');
return rows.map(r => {
  const o = {};
  keepCols.forEach(c => { o[c] = r[c]; });
  return { json: o };
});
